def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_prev, opp_prev = history[-1]
    opp_d = 0
    my_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
    opp_c = n - opp_d

    if opp_c == 0 and n >= 8:
        return 'D'
    if n < 8:
        return 'C'

    opp_d_streak = 0
    for _, b in reversed(history):
        if b == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for _, b in reversed(history):
        if b == 'C':
            opp_c_streak += 1
        else:
            break

    recent_len = n if n < 10 else 10
    recent = history[-recent_len:]
    recent_opp_d = 0
    for _, b in recent:
        if b == 'D':
            recent_opp_d += 1
    recent_opp_c = recent_len - recent_opp_d

    dp = 0
    dc = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'D':
                dp += 1
            else:
                dc += 1

    if opp_d == 0:
        if n < 20:
            return 'C'
        if my_d == 0:
            return 'D'
        if my_d == 1 and my_prev == 'D':
            return 'C'
        return 'D'

    if opp_prev == 'C':
        if my_prev == 'D' and dp == 0 and dc == 0:
            return 'C'

        if dp == 0 and dc >= 1:
            return 'D'

        if dp > 0:
            if opp_d * 3 >= n * 2 and recent_opp_d >= 5:
                return 'D'
            if opp_d > opp_c and recent_opp_d >= recent_opp_c and n >= 20:
                return 'D'
            return 'C'

        if (
            n >= 20
            and my_d == 0
            and opp_c > opp_d
            and recent_opp_c >= recent_opp_d
            and opp_c_streak >= 3
        ):
            return 'D'

        if n >= 12 and opp_d * 2 >= n:
            return 'D'
        if n >= 12 and opp_d * 3 >= n and recent_opp_d >= 4:
            return 'D'

        return 'C'

    if dc >= 2 and dp == 0:
        return 'D'

    if (
        opp_d <= max(4, n // 10)
        and opp_c >= opp_d
        and opp_d_streak <= 5
    ):
        return 'C'

    if (
        my_prev == 'D'
        and opp_c >= opp_d
        and opp_d_streak <= 6
        and recent_opp_c >= 3
    ):
        return 'C'

    if recent_opp_d >= 6:
        return 'D'
    if n >= 16 and opp_d * 3 >= n and recent_opp_d >= 5:
        return 'D'
    if n >= 12 and opp_d * 2 >= n:
        return 'D'

    return 'C'
